// covers: integration dyna:graph.Graph dyna:graph.graph -- every analytics method and its CSR twin against networkx reference vectors
// Graph analytics (Graph methods and the `graph` CSR functions of dyna:structures) against networkx.
// tests/corpus/ref/graph_vectors.js is generated by tests/ref/gen_graph_ref_vectors.py; it stores only the
// answers -- every graph is rebuilt here from the same splitmix64 stream (BigInt, so Python and JS see
// the identical edge list, parallel edges and self loops included). Each call runs twice, once as a
// Graph method and once as the free function over g.exportCSR(), and both must match networkx and
// each other bit for bit. Tolerances: 1e-9 relative for iterative/accumulated floats (PageRank
// stops at the same L1 criterion as networkx but sums in another order), exact for integers and
// partitions. Louvain's partition is implementation-random, so only its modularity is held to
// networkx's (>= nx - 0.02) and to the definition.
import { sections as __kitSections } from "../lib/kit.js";
const __kitS = __kitSections("test_graph_graph_analytics_ref");
import { Graph, graph } from "dyna:graph";
import { CASES, BIG } from "../corpus/ref/graph_vectors.js";

let pass = 0, fail = 0;
const ok = (c, m) => { if (c) pass++; else { fail++; print("FAIL: " + m); } };
const M64 = (1n << 64n) - 1n;

function splitmix(seed) {
    let s = BigInt(seed) & M64;
    return () => {
        s = (s + 0x9E3779B97F4A7C15n) & M64;
        let z = s;
        z = ((z ^ (z >> 30n)) * 0xBF58476D1CE4E5B9n) & M64;
        z = ((z ^ (z >> 27n)) * 0x94D049BB133111EBn) & M64;
        return z ^ (z >> 31n);
    };
}

function build(spec) {
    const r = splitmix(spec.seed), edges = [];
    const wt = () => (spec.weighted ? 1 + Number(r() % 9n) : 1);
    let n;
    if (spec.kind === "gnm") {
        n = spec.n;
        for (let i = 0; i < spec.m; i++) {
            const u = Number(r() % BigInt(n)), v = Number(r() % BigInt(n));
            edges.push([u, v, wt()]);
        }
    } else if (spec.kind === "planted") {
        n = spec.k * spec.size;
        for (let u = 0; u < n; u++)
            for (let v = u + 1; v < n; v++) {
                const p = Math.floor(u / spec.size) === Math.floor(v / spec.size) ? spec.pin : spec.pout;
                if (r() % 1000000n < BigInt(p)) edges.push([u, v, wt()]);
            }
    } else if (spec.kind === "dag") {
        n = spec.n;
        for (let i = 0; i < spec.m; i++) {
            const u = Number(r() % BigInt(n)), v = Number(r() % BigInt(n));
            if (u !== v) edges.push([Math.min(u, v), Math.max(u, v), wt()]);
        }
    } else if (spec.kind === "bip") {
        n = spec.left + spec.right;
        for (let i = 0; i < spec.m; i++) {
            const u = Number(r() % BigInt(spec.left)), v = spec.left + Number(r() % BigInt(spec.right));
            edges.push([u, v, wt()]);
        }
    }
    return { n, edges };
}

function close(a, b, rel = 1e-9, abs = 1e-12) {
    if (Number.isNaN(a) && Number.isNaN(b)) return true;
    return Math.abs(a - b) <= abs + rel * Math.max(Math.abs(a), Math.abs(b));
}
function vecClose(got, want, rel, abs) {
    if (got.length !== want.length) return `length ${got.length} vs ${want.length}`;
    for (let i = 0; i < want.length; i++)
        if (!close(got[i], want[i], rel, abs)) return `[${i}] ${got[i]} vs ${want[i]}`;
    return "";
}
function same(a, b) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!Object.is(a[i], b[i])) return false;
    return true;
}
const canon = (labels) => {
    const first = new Map(), out = [];
    for (let v = 0; v < labels.length; v++) if (!first.has(labels[v])) first.set(labels[v], v);
    for (let v = 0; v < labels.length; v++) out.push(first.get(labels[v]));
    return out;
};
function modularityDef(n, edges, directed, comm, gamma) {
    let m = 0;
    const kin = new Float64Array(n), kout = new Float64Array(n), L = new Map();
    for (const [u, v, w] of edges) {
        m += w;
        kout[comm[u]] += w;
        kin[comm[v]] += w;
        if (comm[u] === comm[v]) L.set(comm[u], (L.get(comm[u]) ?? 0) + w);
    }
    if (m === 0) return 0;
    let q = 0;
    for (let c = 0; c < n; c++) {
        const k = kout[c] + kin[c];
        q += directed ? (L.get(c) ?? 0) / m - (gamma * kout[c] * kin[c]) / (m * m) : (L.get(c) ?? 0) / m - gamma * (k / (2 * m)) ** 2;
    }
    return q;
}

async function both(g, csr, name, ...args) {
    const a = await g[name](...args), b = await graph[name](csr, ...args);
    return [a, b];
}

await __kitS.section("pageRank", async () => {
for (const C of CASES) {
    const { n, edges } = build(C.spec), R = C.results, tag = C.name;
    ok(n === C.n && edges.length === C.m, `${tag}: rebuilt graph has ${C.n} nodes and ${C.m} edges`);
    const g = new Graph({ directed: C.directed, weighted: !!C.spec.weighted });
    for (let i = 0; i < n; i++) g.addNode();
    for (const [u, v, w] of edges) g.addEdge(u, v, w);
    const csr = g.exportCSR();
    ok(csr.directed === C.directed && (C.spec.weighted ? csr.weights instanceof Float64Array : csr.weights === undefined), `${tag}: exportCSR carries directed and weights`);

    let [a, b] = await both(g, csr, "pageRank", { tolerance: 1e-12, maxIterations: 10000 });
    let why = vecClose(a, R.pagerank, 1e-9, 1e-13);
    ok(!why && same(a, b), `${tag}: pageRank equals networkx ${why}`);
    const pers = Float64Array.from({ length: n }, (_, v) => (v === 0 ? 1 : v % 5));
    [a, b] = await both(g, csr, "pageRank", { tolerance: 1e-12, maxIterations: 10000, personalization: pers });
    why = vecClose(a, R.pagerankPersonal, 1e-9, 1e-13);
    ok(!why && same(a, b), `${tag}: personalized pageRank equals networkx ${why}`);

    [a, b] = await both(g, csr, "triangles");
    ok(a.total === R.triangleTotal && !vecClose(a.perVertex, R.triangles, 0, 0) && same(a.perVertex, b.perVertex), `${tag}: triangles equal networkx (${a.total} vs ${R.triangleTotal})`);
    [a, b] = await both(g, csr, "clustering");
    why = vecClose(a.local, R.clustering, 1e-12, 1e-15);
    ok(!why && close(a.average, R.averageClustering, 1e-12) && close(a.transitivity, R.transitivity, 1e-12) && same(a.local, b.local),
        `${tag}: clustering / averageClustering / transitivity equal networkx ${why} ${a.average} ${R.averageClustering} ${a.transitivity} ${R.transitivity}`);
    [a, b] = await both(g, csr, "coreNumbers");
    ok(!vecClose(a, R.coreNumbers, 0, 0) && same(a, b), `${tag}: coreNumbers equal networkx`);
    [a, b] = await both(g, csr, "weaklyConnectedComponents");
    ok(same(canon(a.labels), R.wcc) && a.count === new Set(R.wcc).size && same(a.labels, b.labels), `${tag}: weak components equal networkx`);
    if (C.directed) {
        [a, b] = await both(g, csr, "stronglyConnectedComponents");
        ok(same(canon(a.labels), R.scc) && a.count === new Set(R.scc).size && same(a.labels, b.labels), `${tag}: strong components equal networkx`);
        let climbs = 0;
        for (const [u, v] of edges) if (a.labels[u] < a.labels[v]) climbs++;
        ok(climbs === 0, `${tag}: no arc goes from a lower to a higher SCC id (reverse topological numbering)`);
        if (R.levels) {
            [a, b] = await both(g, csr, "topologicalLevels");
            ok(same(Array.from(a.labels), R.levels) && a.count === Math.max(-1, ...R.levels) + 1 && same(a.labels, b.labels), `${tag}: topologicalLevels equal networkx topological_generations`);
        } else {
            let err = null;
            try { await g.topologicalLevels(); } catch (e) { err = e; }
            ok(err instanceof RangeError && /cycle/.test(err.message), `${tag}: topologicalLevels rejects a cyclic graph`);
        }
    }

    if (R.betweenness) {
        [a, b] = await both(g, csr, "betweenness", { weighted: false });
        why = vecClose(a, R.betweenness, 1e-9, 1e-13);
        ok(!why && same(a, b), `${tag}: betweenness equals networkx ${why}`);
        [a] = await both(g, csr, "betweenness", { weighted: false, normalized: false });
        ok(!vecClose(a, R.betweennessRaw, 1e-9, 1e-12), `${tag}: unnormalized betweenness equals networkx`);
        [a] = await both(g, csr, "betweenness", { weighted: false, endpoints: true });
        ok(!vecClose(a, R.betweennessEndpoints, 1e-9, 1e-13), `${tag}: endpoint betweenness equals networkx`);
        [a, b] = await both(g, csr, "betweenness", { weighted: false, sources: R.betweennessSources });
        why = vecClose(a, R.betweennessSampled, 1e-9, 1e-13);
        ok(!why && same(a, b), `${tag}: betweenness over ${R.betweennessSources.length} sources equals networkx's sampled estimator ${why}`);
        [a, b] = await both(g, csr, "closeness", { weighted: false });
        why = vecClose(a, R.closeness, 1e-12, 1e-15);
        ok(!why && same(a, b), `${tag}: closeness equals networkx ${why}`);
        [a] = await both(g, csr, "closeness", { weighted: false, wfImproved: false });
        ok(!vecClose(a, R.closenessNoWf, 1e-12, 1e-15), `${tag}: closeness without Wasserman-Faust equals networkx`);
        if (R.betweennessWeighted) {
            [a, b] = await both(g, csr, "betweenness");
            why = vecClose(a, R.betweennessWeighted, 1e-9, 1e-13);
            ok(!why && same(a, b), `${tag}: weighted betweenness equals networkx ${why}`);
            [a, b] = await both(g, csr, "closeness");
            why = vecClose(a, R.closenessWeighted, 1e-12, 1e-15);
            ok(!why && same(a, b), `${tag}: weighted closeness equals networkx ${why}`);
        }
        for (const method of ["jaccard", "adamicAdar", "resourceAllocation", "commonNeighbors", "preferentialAttachment"]) {
            [a, b] = await both(g, csr, "linkPrediction", R.pairs, { method });
            why = vecClose(a, R[method], 1e-12, 1e-15);
            ok(!why && same(a, b), `${tag}: linkPrediction ${method} equals networkx ${why}`);
        }
        const flat = Int32Array.from(R.pairs.flat());
        ok(same(await g.linkPrediction(flat), await g.linkPrediction(R.pairs)), `${tag}: flat and nested pairs agree`);
    }

    const part = Int32Array.from({ length: n }, (_, v) => v % 4);
    [a, b] = await both(g, csr, "modularity", part);
    ok(close(a, R.modularity, 1e-12, 1e-15) && a === b, `${tag}: modularity equals networkx (${a} vs ${R.modularity})`);
    [a] = await both(g, csr, "modularity", part, { resolution: 0.7 });
    ok(close(a, R.modularity07, 1e-12, 1e-15), `${tag}: modularity at resolution 0.7 equals networkx`);
    if (R.louvainModularity !== undefined) {
        const lv = await g.louvain({ seed: 3 }), lf = await graph.louvain(csr, { seed: 3 });
        const qdef = modularityDef(n, edges, false, lv.communities, 1);
        ok(close(lv.modularity, qdef, 1e-9, 1e-12) && close(await g.modularity(lv.communities), qdef, 1e-9, 1e-12), `${tag}: louvain's reported modularity ${lv.modularity} is the definition ${qdef}`);
        ok(lv.modularity >= R.louvainModularity - 0.02, `${tag}: louvain modularity ${lv.modularity} reaches networkx's ${R.louvainModularity}`);
        ok(same(lv.communities, lf.communities) && lv.levels >= (n ? 1 : 0), `${tag}: louvain is deterministic for a seed across both forms`);
        const lp = await g.labelPropagation({ seed: 5 });
        let bad = 0;
        const adj = Array.from({ length: n }, () => new Set());
        for (const [u, v] of edges) if (u !== v) { adj[u].add(v); adj[v].add(u); }
        for (let u = 0; u < n; u++) {
            if (!adj[u].size) continue;
            const cnt = new Map();
            for (const v of adj[u]) cnt.set(lp[v], (cnt.get(lp[v]) ?? 0) + (C.spec.weighted ? 0 : 1));
            if (C.spec.weighted) continue;
            const top = Math.max(...cnt.values());
            if (cnt.get(lp[u]) !== top) bad++;
        }
        ok(bad === 0, `${tag}: labelPropagation stops at a labelling where every node holds a most frequent neighbour label (${bad} do not)`);
    }
    if (R.maxFlow !== undefined) {
        [a, b] = await both(g, csr, "maxFlow", 0, n - 1);
        ok(close(a.value, R.maxFlow, 0, 1e-9) && a.value === b.value && same(a.flows, b.flows), `${tag}: maxFlow equals networkx (${a.value} vs ${R.maxFlow})`);
        const net = new Float64Array(n);
        let capBad = 0;
        for (let u = 0; u < n; u++)
            for (let k = csr.offsets[u]; k < csr.offsets[u + 1]; k++) {
                const f = a.flows[k], cap = csr.weights ? csr.weights[k] : 1;
                if (!(f >= 0 && f <= cap + 1e-9)) capBad++;
                net[u] += f;
                net[csr.edges[k]] -= f;
            }
        let consBad = 0;
        for (let v = 1; v < n - 1; v++) if (!close(net[v], 0, 0, 1e-9)) consBad++;
        ok(capBad === 0 && consBad === 0 && close(net[0], a.value, 0, 1e-9) && close(net[n - 1], -a.value, 0, 1e-9), `${tag}: maxFlow flows respect capacities (${capBad} over), conserve at inner nodes (${consBad} leak) and carry the value out of the source`);
        let cut = 0;
        for (let u = 0; u < n; u++)
            for (let k = csr.offsets[u]; k < csr.offsets[u + 1]; k++)
                if (a.sourceSide[u] && !a.sourceSide[csr.edges[k]] && u !== csr.edges[k]) cut += csr.weights ? csr.weights[k] : 1;
        ok(close(cut, a.value, 0, 1e-9) && a.sourceSide[0] === 1 && a.sourceSide[n - 1] === 0, `${tag}: the reported source side is a minimum cut`);
    }
    if (R.matching !== undefined) {
        [a, b] = await both(g, csr, "bipartiteMatching");
        const left = Array.from({ length: n }, (_, v) => v < C.spec.left);
        const c = await g.bipartiteMatching({ left });
        let consistent = true;
        for (let v = 0; v < n; v++) if (a.mate[v] >= 0 && a.mate[a.mate[v]] !== v) consistent = false;
        ok(a.size === R.matching && c.size === R.matching && consistent && same(a.mate, b.mate), `${tag}: bipartiteMatching size equals networkx hopcroft_karp (${a.size} vs ${R.matching})`);
    }
}
});

await __kitS.section("segment L238", async () => {
for (const C of BIG) {
    const { n, edges } = build(C.spec), R = C.results, tag = C.name;
    const g = new Graph({ directed: C.directed });
    for (let i = 0; i < n; i++) g.addNode();
    for (const [u, v] of edges) g.addEdge(u, v);
    const pr = await g.pageRank({ tolerance: 1e-12, maxIterations: 10000 });
    const why = vecClose(pr, R.pagerank, 1e-9, 1e-13);
    ok(!why, `${tag}: pageRank equals networkx ${why}`);
    const t = await g.triangles(), c = await g.clustering(), k = await g.coreNumbers();
    ok(t.total === R.triangleTotal && !vecClose(t.perVertex, R.triangles, 0, 0), `${tag}: triangles equal networkx`);
    ok(close(c.average, R.averageClustering, 1e-12) && close(c.transitivity, R.transitivity, 1e-12), `${tag}: clustering equals networkx`);
    ok(Math.max(...k) === R.coreMax && k.reduce((s, x) => s + x, 0) === R.coreSum, `${tag}: core numbers equal networkx`);
    const lv = await g.louvain();
    ok(lv.modularity >= R.louvainModularity - 0.02, `${tag}: louvain modularity ${lv.modularity} reaches networkx's ${R.louvainModularity}`);
}
});
__kitS.end();

print(`test_structures_graph_analytics_ref: ${pass} passed, ${fail} failed`);
if (fail) throw new Error(`${fail} graph analytics reference checks failed`);
